$(document).ready(function() {

	/** Default Daialog Function  */

	function dialogBox(type, status, message) {
		Swal.fire(
			type,
			message,
			status
		)
	}


	/** Manage Website */

	// Create New Website

	$('#addWebsite').click(function(e) {

		var data = new FormData(document.getElementById('profileData'));
		var username=$('#checkUsername').val();
		$.ajax({
			type: 'POST',
			data: data,
			processData: false,
			contentType: false,
			dataType: 'JSON',
			success: function(data) {
				if(data.status==200) {
					error='success';
				} else {
					error='error';
				}

				Swal.fire(
					'Setting',
					data.msg,
					error
				)

			},
			error: function (data) {
				//console.log('Error');
				console.log(data);
			}
		})
		event.preventDefault();

	});

	// Update Website

	$('#updateWebsite').click(function(e) {

		

	});

	/** Check username is available or not */

	$('#checkUsername').on('keyup keypress', function(e) {
		var username = $('#checkUsername').val();
		$.ajax({
			url: window.location.origin + '/api/username.php',
			type: 'GET',
			dataType: 'JSON',
			data: {
				username: username
			},
			success: function(data) {
				if(data.status==200) {
					$('.submitBtn').prop("disabled", false);
					$('.submitBtn').css('display', 'block');
					$('#checkUsername').css({'background': '#28a745', 'color': '#fff'});
				} else {
					$('.submitBtn').css('display', 'none');
					$('#checkUsername').css({'background': '#D01F2A', 'color': '#fff'});
					$('.submitBtn').prop("disabled", true);
					event.preventDefault();
				}
			},
			error: function(data) {
				console.log(data);
			}
		})
	});

	/** Update profile */

	$('#updateProfile').click(function(e) {
		var data = new FormData(document.getElementById('profileData'));
		var username=$('#checkUsername').val();
		$.ajax({
			type: 'POST',
			data: data,
			processData: false,
			contentType: false,
			dataType: 'JSON',
			success: function(data) {
				if(data.status==200) {
					error='success';
				} else {
					error='error';
				}

				Swal.fire(
					'Setting',
					data.msg,
					error
				)

			},
			error: function (data) {
				//console.log('Error');
				console.log(data);
			}
		})
		event.preventDefault();
	});

});